import Config

# Use the same component-aware formatter as dev so thinking logs show [component]
config :logger, :default_formatter,
  format: {MediaCentaur.Log.Formatter, :format},
  metadata: [:component]

# Do not print debug messages in production
config :logger, level: :info

# The path to a cache manifest containing the digested version of static
# files. This manifest is generated by the `mix assets.deploy` task, which
# you should run after static files are built and before starting your
# production server.
config :media_centaur, MediaCentaurWeb.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"
config :media_centaur, :environment, :prod

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
